function LenderOverview({ setPage, openInvite }: { setPage: (p: LenderPage) => void; openInvite: () => void }) {
  return <div className="lender-page"><div className="portal-context"><span><i>●</i> Organization portal</span><p>Summit Home Loans controls invitations, branding, access and routing. Status only — the CRM stays the system of record.</p></div><div className="lender-page-title"><div><span className="section-kicker">TUESDAY · AUGUST 18</span><h1>Good morning, Alex.</h1><p>Three consumers crossed meaningful readiness milestones today.</p></div><button className="primary-lime dark-text" onClick={openInvite}>＋ Invite consumer</button></div><section className="kpi-grid"><Kpi label="Active consumers" value="127" note="↑ 12% from last month" icon="♙" tone="mint" /><Kpi label="Working" value="107" note="active in the last 30 days" icon="↗" tone="lime" /><Kpi label="Enrolled" value="9" note="enrolled this month" icon="◈" tone="purple" /><Kpi label="Review requested" value="18" note="status packets, never reports" icon="◈" tone="dark" dark /></section><div className="overview-grid"><section className="pipeline-card"><div className="card-title-row"><div><span className="section-kicker">READINESS PIPELINE</span><h3>From invited lead to lender review</h3></div><select><option>Last 90 days</option></select></div><div className="funnel-list">{[["Invitations sent", "612", 100], ["Readiness checks", "482", 79], ["Active builders", "267", 44], ["Review requested", "139", 23], ["Applications returned", "82", 13]].map(([label, value, width]) => <div key={label as string} className={width === 13 ? "final" : ""}><span>{label}</span><div><i style={{ width: `${width}%` }} /></div><strong>{value}</strong><small>{width}%</small></div>)}</div><div className="conversion-note"><span>↗</span><p><strong>Status, never reports.</strong><small>Every consumer stays attributed to the originating LO and lead source</small></p></div></section><section className="attention-card"><div className="card-title-row"><div><span className="section-kicker">NEEDS ATTENTION</span><h3>Act while intent is high</h3></div><button onClick={() => setPage("borrowers")}>View all →</button></div><div className="attention-list">{borrowers.slice(1, 4).map((x, i) => <button key={x.name} onClick={() => setPage("borrower")}><span className={`person-avatar ${x.tone}`}>{x.initials}</span><div><strong>{x.name}</strong><small>{i === 0 ? "Threshold reached · Ready for review" : i === 1 ? "Inactive for 14 days" : "Requested lender review"}</small></div><span className={`attention-tag ${i === 1 ? "neutral" : ""}`}>{i === 1 ? "Re-engage" : "Review"} →</span></button>)}</div><div className="journey-health"><div><span>Journey health</span><strong>84%</strong></div><div><i style={{ width: "84%" }} /></div><small>107 of 127 consumers active in the last 30 days</small></div></section></div><section className="borrower-table-card"><div className="card-title-row"><div><span className="section-kicker">RECENT ACTIVITY</span><h3>Consumer readiness</h3></div><button onClick={() => setPage("borrowers")}>Open consumers →</button></div><BorrowerTable onSelect={() => setPage("borrower")} compact /></section></div>;
}

